//! Raw libgpod declarations generated by bindgen (see build.rs).
//!
//! Everything in here is `unsafe` to call. The rest of Oxipod uses the safe
//! wrapper in `gpod/mod.rs` instead.

// The generated code follows C naming, not Rust's.
#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case)]
#![allow(dead_code, unsafe_op_in_unsafe_fn, clippy::all)]

include!(concat!(env!("OUT_DIR"), "/gpod.rs"));
